  1	//! K6's sealed kernel models (T3 D1 §4.8; ROOT's K6 rulings Q10 and N4).
  2	//!
  3	//! - **RF-LARGE** (24 cases): R1's families (`T3/REFERENCES/references.py`,
  4	//!   sha256 `80d473a7…`; `lg_chain_defn`, `lg_tree_defn`, `continuous_defn`,
  5	//!   `rot_defn`), with every node and member in R1's insertion order. Every
  6	//!   coordinate and load is built in exact integer arithmetic (the rotated
  7	//!   cases through Q3 with an exact division by 3) and converted to binary64
  8	//!   once; each is exactly representable.
  9	//! - **The DEC-053 nine**: the harness's own invented fixtures, taken from the
 10	//!   crate's DEC-053 specification list, unchanged.
 11	//! - **Outside the sealed set**: the Q4 ceiling chain (RF-LARGE-CHAIN geometry,
 12	//!   1,364 members) and the Q5 invented grids.
 13	//!
 14	//! No function of unspecified precision is used: the section is formed from
 15	//! explicit products and `std::f64::consts::PI` only.
 16	
 17	use crate::{invented_grid_frame_fixture, BenchmarkFixture};
 18	use open_pipe_stress_frame_kernel::{
 19	    FrameElement, FrameKernelError, FrameNode, FrameSection, DOF_PER_NODE,
 20	};
 21	use std::f64::consts::PI;
 22	
 23	/// The source label of R1's models (references.json sha256 `7b176dbb…`).
 24	pub const R1_SOURCE: &str = "r1:references.json@7b176dbb";
 25	/// RF-LARGE's member counts.
 26	pub const RF_LARGE_SIZES: [usize; 4] = [10, 100, 1000, 10000];
 27	/// The Q4 ceiling chain's member count (8,190 DOFs; ROOT's K6 ruling Q4).
 28	pub const CEILING_CHAIN_MEMBERS: usize = 1364;
 29	/// The Q5 grid sides (ROOT's K6 ruling N14; 128 is conditional).
 30	pub const Q5_GRID_SIDES: [usize; 5] = [16, 32, 64, 96, 128];
 31	/// The CONT size whose identity-order lane is never run (Q12).
 32	pub const CONT_LANE_REFUSAL_MEMBERS: usize = 10_000;
 33	
 34	/// The model family, for the runner's admission ratios.
 35	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 36	pub enum Family {
 37	    Chain,
 38	    Tree,
 39	    Cont,
 40	    Dec053,
 41	    Grid,
 42	}
 43	
 44	impl Family {
 45	    pub fn as_str(self) -> &'static str {
 46	        match self {
 47	            Self::Chain => "CHAIN",
 48	            Self::Tree => "TREE",
 49	            Self::Cont => "CONT",
 50	            Self::Dec053 => "DEC053",
 51	            Self::Grid => "GRID",
 52	        }
 53	    }
 54	}
 55	
 56	/// A kernel model: one section, nodes and members in their authored order,
 57	/// restraints and nodal loads (global DOF, value).
 58	#[derive(Debug, Clone, PartialEq)]
 59	pub struct K6Model {
 60	    pub id: String,
 61	    pub source: String,
 62	    pub family: Family,
 63	    pub section: FrameSection,
 64	    /// (label, coordinates), in the model's node order (node index = position).
 65	    pub nodes: Vec<(String, [f64; 3])>,
 66	    /// (label, node i, node j, y_reference), in the model's member order.
 67	    pub members: Vec<(String, usize, usize, [f64; 3])>,
 68	    /// (node, restrained UX UY UZ RX RY RZ), ascending node.
 69	    pub restraints: Vec<(usize, [bool; 6])>,
 70	    /// (global DOF, value), ascending DOF, nonzero only.
 71	    pub loads: Vec<(usize, f64)>,
 72	}
 73	
 74	impl K6Model {
 75	    pub fn node_count(&self) -> usize {
 76	        self.nodes.len()
 77	    }
 78	    pub fn member_count(&self) -> usize {
 79	        self.members.len()
 80	    }
 81	    pub fn dofs(&self) -> usize {
 82	        self.nodes.len() * DOF_PER_NODE
 83	    }
 84	    /// The frames, formed by `FrameElement::new` in member order.
 85	    pub fn frames(&self) -> Result<Vec<FrameElement>, FrameKernelError> {
 86	        self.members
 87	            .iter()
 88	            .map(|(_, i, j, y)| {
 89	                FrameElement::new(
 90	                    FrameNode::new(*i, self.nodes[*i].1)?,
 91	                    FrameNode::new(*j, self.nodes[*j].1)?,
 92	                    self.section,
 93	                    *y,
 94	                )
 95	            })
 96	            .collect()
 97	    }
 98	    /// The restrained global DOFs, ascending.
 99	    pub fn restrained_dofs(&self) -> Vec<usize> {
100	        self.restraints
101	            .iter()
102	            .flat_map(|(node, mask)| {
103	                (0..DOF_PER_NODE)
104	                    .filter(move |&d| mask[d])
105	                    .map(move |d| node * DOF_PER_NODE + d)
106	            })
107	            .collect()
108	    }
109	    /// The global nodal force vector (one term per loaded DOF).
110	    pub fn force_vector(&self) -> Vec<f64> {
111	        let mut force = vec![0.0; self.dofs()];
112	        for &(dof, value) in &self.loads {
113	            force[dof] = value;
114	        }
115	        force
116	    }
117	    /// R1's CONT case at 10,000 members or more, whose identity-order lane is
118	    /// never run (ROOT's K6 ruling Q12, restated with RV16-N4).
119	    ///
120	    /// Decided from the model's content, not its id (RV18-N6), since a model
121	    /// file carries its own id: the family is CONT (as generated, or as R1's
122	    /// id names it), or the model carries CONT's restraint signature. That
123	    /// signature is m + 1 nodes, the first fully fixed and the next m/2 pinned
124	    /// in UX, UY and UZ, and nothing else restrained. The size is the member
125	    /// count.
126	    pub fn is_cont_n10000(&self) -> bool {
127	        self.member_count() >= CONT_LANE_REFUSAL_MEMBERS
128	            && (self.family == Family::Cont || self.has_cont_restraints())
129	    }
130	
131	    fn has_cont_restraints(&self) -> bool {
132	        let supports = self.member_count() / 2;
133	        self.node_count() == self.member_count() + 1
134	            && self.restraints.len() == supports + 1
135	            && self.restraints.iter().enumerate().all(|(k, (node, mask))| {
136	                *node == k && *mask == if k == 0 { ALL_SIX } else { PIN_THREE }
137	            })
138	    }
139	}
