141	/// The 33 sealed models: RF-LARGE's 24 (family, size, orientation), then the
142	/// DEC-053 nine in the harness's order.
143	pub fn sealed_model_ids() -> Vec<String> {
144	    let mut ids = Vec::new();
145	    for family in ["CHAIN", "TREE", "CONT"] {
146	        for n in RF_LARGE_SIZES {
147	            for orientation in ["AX", "ROT"] {
148	                ids.push(format!("RF-LARGE-{family}-n{n:05}-{orientation}"));
149	            }
150	        }
151	    }
152	    for spec in crate::sparse_default_promotion_fixture_specs() {
153	        if let Ok(fixture) = spec.fixture() {
154	            ids.push(format!("DEC053:{}", fixture.fixture_id));
155	        }
156	    }
157	    ids
158	}
