160	/// The models outside the sealed set: the Q4 ceiling chain and the Q5 grids.
161	pub fn extra_model_ids() -> Vec<String> {
162	    let mut ids = vec![format!("K6-CEIL-CHAIN-n{CEILING_CHAIN_MEMBERS:05}-AX")];
163	    for side in Q5_GRID_SIDES {
164	        ids.push(format!("K6-GRID-{side}x{side}"));
165	    }
166	    ids
167	}
