169	/// Builds a model by id.
170	pub fn model(id: &str) -> Result<K6Model, String> {
171	    if let Some(rest) = id.strip_prefix("RF-LARGE-") {
172	        return rf_large(id, rest);
173	    }
174	    if let Some(fixture_id) = id.strip_prefix("DEC053:") {
175	        for spec in crate::sparse_default_promotion_fixture_specs() {
176	            let fixture = spec.fixture().map_err(|e| format!("{e:?}"))?;
177	            if fixture.fixture_id == fixture_id {
178	                return from_fixture(id, &format!("dec053:{fixture_id}"), Family::Dec053, fixture);
179	            }
180	        }
181	        return Err(format!("unknown DEC-053 fixture: {fixture_id}"));
182	    }
183	    if id == format!("K6-CEIL-CHAIN-n{CEILING_CHAIN_MEMBERS:05}-AX") {
184	        let (s, s2) = chain_exponents(CEILING_CHAIN_MEMBERS).ok_or("no chain exponents")?;
185	        return Ok(chain(
186	            id,
187	            "k6-invented:rf-large-chain-rule",
188	            CEILING_CHAIN_MEMBERS,
189	            false,
190	            s,
191	            s2,
192	        ));
193	    }
194	    if let Some(rest) = id.strip_prefix("K6-GRID-") {
195	        let side: usize = rest
196	            .split_once('x')
197	            .filter(|(a, b)| a == b)
198	            .and_then(|(a, _)| a.parse().ok())
199	            .filter(|s| Q5_GRID_SIDES.contains(s))
200	            .ok_or_else(|| format!("unknown grid: {id}"))?;
201	        let fixture = invented_grid_frame_fixture(side, side).map_err(|e| format!("{e:?}"))?;
202	        return from_fixture(
203	            id,
204	            "k6-invented:invented_grid_frame_fixture",
205	            Family::Grid,
206	            fixture,
207	        );
208	    }
209	    Err(format!("unknown model id: {id}"))
210	}
