212	fn rf_large(id: &str, rest: &str) -> Result<K6Model, String> {
213	    let parts: Vec<&str> = rest.split('-').collect();
214	    let [family, size, orientation] = parts.as_slice() else {
215	        return Err(format!("malformed RF-LARGE id: {id}"));
216	    };
217	    let n: usize = size
218	        .strip_prefix('n')
219	        .filter(|digits| digits.len() == 5)
220	        .and_then(|digits| digits.parse().ok())
221	        .filter(|n| RF_LARGE_SIZES.contains(n))
222	        .ok_or_else(|| format!("unknown RF-LARGE size: {id}"))?;
223	    let rotated = match *orientation {
224	        "AX" => false,
225	        "ROT" => true,
226	        _ => return Err(format!("unknown orientation: {id}")),
227	    };
228	    match *family {
229	        "CHAIN" => {
230	            let (s, s2) = chain_exponents(n).ok_or("no chain exponents")?;
231	            Ok(chain(id, R1_SOURCE, n, rotated, s, s2))
232	        }
233	        "TREE" => Ok(tree(
234	            id,
235	            n,
236	            rotated,
237	            tree_exponent(n).ok_or("no tree exponent")?,
238	        )),
239	        "CONT" => Ok(cont(id, n, rotated)),
240	        _ => Err(format!("unknown RF-LARGE family: {id}")),
241	    }
242	}
