244	/// CHAIN's load exponents (s, s2): R1's `round(log2(1.264/n²))` and
245	/// `round(log2(24.5/n))` (`lg_chain_defn`), tabulated and re-derived by exact
246	/// rational comparison (2^(2k-1) <= x² < 2^(2k+1)). They reproduce the tip
247	/// loads of `references.json` at n = 10, 100, 1,000 and 10,000. n = 1,364 is
248	/// the Q4 chain, by the same rule.
249	pub fn chain_exponents(n: usize) -> Option<(i32, i32)> {
250	    match n {
251	        10 => Some((-6, 1)),
252	        100 => Some((-13, -2)),
253	        1000 => Some((-20, -5)),
254	        10000 => Some((-26, -9)),
255	        CEILING_CHAIN_MEMBERS => Some((-20, -6)),
256	        _ => None,
257	    }
258	}
259	
260	/// TREE's load exponent sc, which R1 derives from its exact solution
261	/// (`round(log2(1e-4/max_rotation))`, `references.py:1889`). It is data, read
262	/// from `references.json`'s purpose strings and checked by the recorded
263	/// cross-check against `references.py --model`.
264	pub fn tree_exponent(n: usize) -> Option<i32> {
265	    match n {
266	        10 => Some(0),
267	        100 => Some(-6),
268	        1000 => Some(-14),
269	        10000 => Some(-20),
270	        _ => None,
271	    }
272	}
273	
274	/// The RF-LARGE section: E = 200 GPa, G = 80 GPa, OD = 0.2 m and ID = 0.18 m,
275	/// each rounded once; A, I and J from explicit products and `PI` only:
276	/// `A = PI*(od²-id²)/4`, `I = PI*(od²·od² - id²·id²)/64`, `J = 2I`, with
277	/// od² = od*od and id² = id*id, evaluated left to right.
278	pub fn rf_large_section() -> FrameSection {
279	    let elastic_modulus = 200_000_000_000.0_f64;
280	    let shear_modulus = 80_000_000_000.0_f64;
281	    let od = 0.2_f64;
282	    let id = 0.18_f64;
283	    let od2 = od * od;
284	    let id2 = id * id;
285	    let area = PI * (od2 - id2) / 4.0;
286	    let second_moment = PI * (od2 * od2 - id2 * id2) / 64.0;
287	    let torsion_constant = 2.0 * second_moment;
288	    FrameSection::new(
289	        elastic_modulus,
290	        shear_modulus,
291	        area,
292	        second_moment,
293	        second_moment,
294	        torsion_constant,
295	    )
296	    .expect("the RF-LARGE section is positive and finite")
297	}
