299	/// Q3 = (1/3)[[1,2,2],[2,1,-2],[-2,2,-1]] (`references.py:1298`) applied to an
300	/// integer vector, with the division by 3 checked exact.
301	fn q3(v: [i64; 3]) -> [i64; 3] {
302	    let r = [
303	        v[0] + 2 * v[1] + 2 * v[2],
304	        2 * v[0] + v[1] - 2 * v[2],
305	        -2 * v[0] + 2 * v[1] - v[2],
306	    ];
307	    assert!(
308	        r.iter().all(|c| c % 3 == 0),
309	        "Q3 image of {v:?} is not an integer vector"
310	    );
311	    [r[0] / 3, r[1] / 3, r[2] / 3]
312	}
313	
314	fn oriented(v: [i64; 3], rotated: bool) -> [i64; 3] {
315	    if rotated {
316	        q3(v)
317	    } else {
318	        v
319	    }
320	}
321	
322	/// 2^e, exactly (normal range only).
323	fn pow2(e: i32) -> f64 {
324	    assert!((-1022..=1023).contains(&e));
325	    f64::from_bits(((1023 + e) as u64) << 52)
326	}
327	
328	fn coordinates(v: [i64; 3]) -> [f64; 3] {
329	    [v[0] as f64, v[1] as f64, v[2] as f64]
330	}
331	
332	/// P1's `y_reference` rule (`T3/DETECTION/scripts/gen.py.txt`): the global
333	/// axis least aligned with the member, preferring Y, then Z, then X on ties,
334	/// from the exact integer coordinate difference.
335	pub fn p1_y_reference(pi: [i64; 3], pj: [i64; 3]) -> [f64; 3] {
336	    let magnitudes = [
337	        (pj[0] - pi[0]).abs(),
338	        (pj[1] - pi[1]).abs(),
339	        (pj[2] - pi[2]).abs(),
340	    ];
341	    let mut best = 1;
342	    for axis in [2, 0] {
343	        if magnitudes[axis] < magnitudes[best] {
344	            best = axis;
345	        }
346	    }
347	    let mut y = [0.0; 3];
348	    y[best] = 1.0;
349	    y
350	}
351	
352	/// Accumulates an integer model and converts it once.
353	struct Builder {
354	    points: Vec<(String, [i64; 3])>,
355	    members: Vec<(String, usize, usize)>,
356	    restraints: Vec<(usize, [bool; 6])>,
357	    loads: Vec<(usize, f64)>,
358	}
359	
360	impl Builder {
361	    fn new() -> Self {
362	        Self {
363	            points: Vec::new(),
364	            members: Vec::new(),
365	            restraints: Vec::new(),
366	            loads: Vec::new(),
367	        }
368	    }
369	    fn node(&mut self, label: String, p: [i64; 3]) -> usize {
370	        self.points.push((label, p));
371	        self.points.len() - 1
372	    }
373	    /// A force (or, with `offset` 3, a moment) at `node`: each nonzero
374	    /// component `c * 2^exponent`, exact.
375	    fn load(&mut self, node: usize, offset: usize, v: [i64; 3], exponent: i32) {
376	        for (axis, &c) in v.iter().enumerate() {
377	            if c != 0 {
378	                assert!(c.unsigned_abs() < (1_u64 << 53));
379	                self.loads.push((
380	                    node * DOF_PER_NODE + offset + axis,
381	                    c as f64 * pow2(exponent),
382	                ));
383	            }
384	        }
385	    }
386	    fn finish(mut self, id: &str, source: &str, family: Family) -> K6Model {
387	        self.loads.sort_by_key(|&(dof, _)| dof);
388	        self.restraints.sort_by_key(|&(node, _)| node);
389	        let members = self
390	            .members
391	            .iter()
392	            .map(|(label, i, j)| {
393	                (
394	                    label.clone(),
395	                    *i,
396	                    *j,
397	                    p1_y_reference(self.points[*i].1, self.points[*j].1),
398	                )
399	            })
400	            .collect();
401	        K6Model {
402	            id: id.to_string(),
403	            source: source.to_string(),
404	            family,
405	            section: rf_large_section(),
406	            nodes: self
407	                .points
408	                .into_iter()
409	                .map(|(label, p)| (label, coordinates(p)))
410	                .collect(),
411	            members,
412	            restraints: self.restraints,
413	            loads: self.loads,
414	        }
415	    }
416	}
417	
418	const ALL_SIX: [bool; 6] = [true; 6];
419	const PIN_THREE: [bool; 6] = [true, true, true, false, false, false];
420	
421	/// R1's CHAIN (`lg_chain_defn`): nodes N0..Nn at (3i, 0, 0), members Mi =
422	/// (N(i-1), Ni), N0 fixed, and at Nn the force 2^s(6,-3,9) and the moment
423	/// 2^s2(3,6,-3); rotated by Q3 when `rotated`.
424	fn chain(id: &str, source: &str, n: usize, rotated: bool, s: i32, s2: i32) -> K6Model {
425	    let mut b = Builder::new();
426	    for i in 0..=n {
427	        b.node(format!("N{i}"), oriented([3 * i as i64, 0, 0], rotated));
428	    }
429	    for i in 1..=n {
430	        b.members.push((format!("M{i}"), i - 1, i));
431	    }
432	    b.restraints.push((0, ALL_SIX));
433	    b.load(n, 0, oriented([6, -3, 9], rotated), s);
434	    b.load(n, 3, oriented([3, 6, -3], rotated), s2);
435	    b.finish(id, source, Family::Chain)
436	}
437	
438	/// R1's TREE (`lg_tree_defn`): P0, then Pk and Bk interleaved; members Sk =
439	/// (P(k-1), Pk) and Qk = (Pk, Bk) interleaved; Bk at +3 in y (k odd) or z (k
440	/// even); the load at Bk is 3((k mod 7) - 3)·2^sc along z (k odd) or y (k
441	/// even), omitted when zero; P0 fixed.
442	fn tree(id: &str, n: usize, rotated: bool, sc: i32) -> K6Model {
443	    let mut b = Builder::new();
444	    let h = n / 2;
445	    let mut spine = vec![b.node("P0".to_string(), [0, 0, 0])];
446	    for k in 1..=h {
447	        let x = 3 * k as i64;
448	        spine.push(b.node(format!("P{k}"), oriented([x, 0, 0], rotated)));
449	        let tip = if k % 2 == 1 { [x, 3, 0] } else { [x, 0, 3] };
450	        let branch = b.node(format!("B{k}"), oriented(tip, rotated));
451	        b.members.push((format!("S{k}"), spine[k - 1], spine[k]));
452	        b.members.push((format!("Q{k}"), spine[k], branch));
453	        let c = (k % 7) as i64 - 3;
454	        if c != 0 {
455	            let force = if k % 2 == 1 {
456	                [0, 0, 3 * c]
457	            } else {
458	                [0, 3 * c, 0]
459	            };
460	            b.load(branch, 0, oriented(force, rotated), sc);
461	        }
462	    }
463	    b.restraints.push((0, ALL_SIX));
464	    b.finish(id, R1_SOURCE, Family::Tree)
465	}
466	
467	/// R1's CONT (`continuous_defn` via `lg_cont_defn`): s = n/2 spans of 6 m;
468	/// nodes S0..Ss, then C1..Cs; members Aj = (S(j-1), Cj) and Bj = (Cj, Sj)
469	/// interleaved; S0 fixed, S1..Ss pinned in UX, UY, UZ; the load at Cj is
470	/// Q(0, 96((j mod 5) - 2), 96((j mod 3) - 1)), omitted when zero.
471	fn cont(id: &str, n: usize, rotated: bool) -> K6Model {
472	    let mut b = Builder::new();
473	    let s = n / 2;
474	    for i in 0..=s {
475	        b.node(format!("S{i}"), oriented([6 * i as i64, 0, 0], rotated));
476	    }
477	    for j in 1..=s {
478	        b.node(
479	            format!("C{j}"),
480	            oriented([3 * (2 * j as i64 - 1), 0, 0], rotated),
481	        );
482	    }
483	    for j in 1..=s {
484	        b.members.push((format!("A{j}"), j - 1, s + j));
485	        b.members.push((format!("B{j}"), s + j, j));
486	    }
487	    b.restraints.push((0, ALL_SIX));
488	    for i in 1..=s {
489	        b.restraints.push((i, PIN_THREE));
490	    }
491	    for j in 1..=s {
492	        let py = 96 * ((j % 5) as i64 - 2);
493	        let pz = 96 * ((j % 3) as i64 - 1);
494	        if py != 0 || pz != 0 {
495	            b.load(s + j, 0, oriented([0, py, pz], rotated), 0);
496	        }
497	    }
498	    b.finish(id, R1_SOURCE, Family::Cont)
499	}
