501	/// A harness fixture as a K6 model: its own section, `y_reference`, force and
502	/// restraints, unchanged. Node labels are `n<i>`, member labels `e<k>`.
503	fn from_fixture(
504	    id: &str,
505	    source: &str,
506	    family: Family,
507	    fixture: BenchmarkFixture,
508	) -> Result<K6Model, String> {
509	    let mut coordinates: Vec<Option<[f64; 3]>> = vec![None; fixture.node_count];
510	    let mut members = Vec::with_capacity(fixture.elements.len());
511	    let section = fixture
512	        .elements
513	        .first()
514	        .map(|e| e.section)
515	        .ok_or("fixture without elements")?;
516	    for (k, element) in fixture.elements.iter().enumerate() {
517	        if element.section != section {
518	            return Err("fixture with more than one section".to_string());
519	        }
520	        for node in [element.node_i, element.node_j] {
521	            coordinates[node.index] = Some(node.coordinates);
522	        }
523	        members.push((
524	            format!("e{k}"),
525	            element.node_i.index,
526	            element.node_j.index,
527	            element.y_reference,
528	        ));
529	    }
530	    let nodes = coordinates
531	        .into_iter()
532	        .enumerate()
533	        .map(|(i, c)| c.map(|c| (format!("n{i}"), c)))
534	        .collect::<Option<Vec<_>>>()
535	        .ok_or("fixture node without an element")?;
536	    let mut restraints: Vec<(usize, [bool; 6])> = Vec::new();
537	    for &dof in &fixture.restrained_dofs {
538	        let node = dof / DOF_PER_NODE;
539	        match restraints.iter_mut().find(|(n, _)| *n == node) {
540	            Some((_, mask)) => mask[dof % DOF_PER_NODE] = true,
541	            None => {
542	                let mut mask = [false; 6];
543	                mask[dof % DOF_PER_NODE] = true;
544	                restraints.push((node, mask));
545	            }
546	        }
547	    }
548	    restraints.sort_by_key(|&(node, _)| node);
549	    let loads = fixture
550	        .force
551	        .iter()
552	        .enumerate()
553	        .filter(|(_, v)| **v != 0.0)
554	        .map(|(dof, v)| (dof, *v))
555	        .collect();
556	    Ok(K6Model {
557	        id: id.to_string(),
558	        source: source.to_string(),
559	        family,
560	        section,
561	        nodes,
562	        members,
563	        restraints,
564	        loads,
565	    })
566	}

  1	//! K6b's W1 counts and the W1 admission estimate (T3 K6b plan §3.4–§3.5;
  2	//! ROOT's rulings on I16's plan).
  3	//!
  4	//! The counts phase works in O(nnz): it builds the adapter's `PrimitiveSource`,
  5	//! the structural free–free adjacency and K4's own RCM order (the exported
  6	//! `reverse_cuthill_mckee`), and counts the skyline by K4's rule
  7	//! (`K4R/factor.rs:351-398`: first = the least rank over a row's neighbours
  8	//! and itself). Nothing is solved. Every count is checked at run time against
  9	//! each attempt's `StorageCounts` (parity lines).
 10	//!
 11	//! The estimate counts the bytes alive at W1's peak, as K6 derived E_adm
 12	//! (K6 plan §7). Sizes of FK's crate-private types are derived from their
 13	//! definitions (the constants below cite them); sizes of exported types come
 14	//! from `size_of`. It is an admission estimate: the measured ratio ρ
 15	//! calibrates it, and nothing asserts a memory bound.
 16	//!
 17	//! It bounds every modelled phase of the schedule, each Vec growth under the
 18	//! allocator's move model (the old and new buffers alive together), which is
 19	//! the model ρ reads: the shared builds, each solve with its fallback, each
 20	//! verification build and pass (with the shift), each decision, and the end
 21	//! (ROOT's ruling on RV22-2).
 22	
