 78	/// Node adjacency of the member graph (sorted, without self) and whether each
 79	/// node carries a member.
 80	fn node_graph(nodes: usize, members: &[StraightMember]) -> (Vec<Vec<usize>>, Vec<bool>) {
 81	    let mut adjacent: Vec<Vec<usize>> = vec![Vec::new(); nodes];
 82	    let mut touched = vec![false; nodes];
 83	    for m in members {
 84	        let (i, j) = (m.node_i as usize, m.node_j as usize);
 85	        adjacent[i].push(j);
 86	        adjacent[j].push(i);
 87	        touched[i] = true;
 88	        touched[j] = true;
 89	    }
 90	    for list in &mut adjacent {
 91	        list.sort_unstable();
 92	        list.dedup();
 93	    }
 94	    (adjacent, touched)
 95	}
