 97	/// K4's profile rule on the structural free–free adjacency: (profile entries,
 98	/// half-bandwidth, blocks).
 99	pub fn structural_profile(
100	    dofs: usize,
101	    free: &[usize],
102	    adjacent: &[Vec<usize>],
103	) -> (usize, usize, usize) {
104	    let mut position = vec![usize::MAX; dofs];
105	    for (a, &g) in free.iter().enumerate() {
106	        position[g] = a;
107	    }
108	    let adjacency: Vec<Vec<usize>> = free
109	        .iter()
110	        .map(|&g| {
111	            let node = g / DOF_PER_NODE;
112	            let mut out = Vec::new();
113	            for &other in std::iter::once(&node).chain(adjacent[node].iter()) {
114	                for c in 0..DOF_PER_NODE {
115	                    let h = other * DOF_PER_NODE + c;
116	                    if h != g && position[h] != usize::MAX {
117	                        out.push(position[h]);
118	                    }
119	                }
120	            }
121	            out
122	        })
123	        .collect();
124	    drop(position);
125	    let order = reverse_cuthill_mckee(&adjacency);
126	    let mut rank = vec![0usize; free.len()];
127	    for (k, &a) in order.iter().enumerate() {
128	        rank[a] = k;
129	    }
130	    let (mut profile, mut bandwidth) = (0usize, 0usize);
131	    for (i, &a) in order.iter().enumerate() {
132	        let first = adjacency[a]
133	            .iter()
134	            .map(|&b| rank[b])
135	            .chain(std::iter::once(i))
136	            .min()
137	            .unwrap_or(i);
138	        profile += i - first + 1;
139	        bandwidth = bandwidth.max(i - first);
140	    }
141	    // Blocks: connected components of the free–free adjacency.
142	    let mut block = vec![usize::MAX; free.len()];
143	    let mut blocks = 0;
144	    let mut stack = Vec::new();
145	    for seed in 0..free.len() {
146	        if block[seed] != usize::MAX {
147	            continue;
148	        }
149	        block[seed] = blocks;
150	        stack.push(seed);
151	        while let Some(a) = stack.pop() {
152	            for &b in &adjacency[a] {
153	                if block[b] == usize::MAX {
154	                    block[b] = blocks;
155	                    stack.push(b);
156	                }
157	            }
158	        }
159	        blocks += 1;
160	    }
161	    (profile, bandwidth, blocks)
162	}
163	
164	/// W1's counts of `model`, in O(nnz) memory, with the source's refusal if
165	/// `PrimitiveSource::new` refuses it.
166	pub fn compute(model: &K6Model) -> (W1Counts, Option<String>) {
167	    let source = match adapter::source(model) {
168	        Ok(source) => source,
169	        Err(error) => {
170	            let counts = W1Counts {
171	                source_ok: false,
172	                nodes: model.node_count(),
173	                members: model.member_count(),
174	                stations: model.member_count(),
175	                constraints: model.restrained_dofs().len(),
176	                loads: model.loads.len(),
177	                dofs: model.dofs(),
178	                free_dofs: 0,
179	                bodies: 0,
180	                pattern_entries: 0,
181	                profile_entries: 0,
182	                half_bandwidth: 0,
183	                blocks: 0,
184	                rows: 0,
185	                source_encoding_len: 0,
186	                source_encoding_fnv64: 0,
187	            };
188	            return (counts, Some(format!("{error:?}")));
189	        }
190	    };
191	    let (adjacent, touched) = node_graph(source.node_count(), source.members());
192	    let pairs: usize = adjacent.iter().map(Vec::len).sum();
193	    let touched = touched.iter().filter(|&&t| t).count();
194	    let pattern_entries = DOF_PER_NODE * DOF_PER_NODE * (touched + pairs);
195	    let free = source.free_dofs();
196	    let (profile_entries, half_bandwidth, blocks) =
197	        structural_profile(source.dof_count(), &free, &adjacent);
198	    let encoding = source.encoding();
199	    let counts = W1Counts {
200	        source_ok: true,
201	        nodes: source.node_count(),
202	        members: source.members().len(),
203	        stations: source.stations().len(),
204	        constraints: source.constraints().len(),
205	        loads: source.loads().len(),
206	        dofs: source.dof_count(),
207	        free_dofs: free.len(),
208	        bodies: source.body_count() as usize,
209	        pattern_entries,
210	        profile_entries,
211	        half_bandwidth,
212	        blocks,
213	        rows: layout(&source).len(),
214	        source_encoding_len: encoding.len(),
215	        source_encoding_fnv64: fnv64(&encoding),
216	    };
217	    (counts, None)
218	}
