408	/// The W1 estimate (plan §3.5; ROOT's ruling on RV22-2). Each phase's
409	/// transient is added to the bytes kept when it runs, so the estimate bounds
410	/// every modelled phase rather than tracking the peak.
411	pub fn estimate(c: &W1Counts, s: &W1SizeFacts) -> W1Estimate {
412	    let u = |x: usize| x as u128;
413	    let (m, n, nf, nnz) = (
414	        u(c.members),
415	        u(c.dofs),
416	        u(c.free_dofs),
417	        u(c.pattern_entries),
418	    );
419	    let (p_entries, blocks, rows) = (u(c.profile_entries), u(c.blocks.max(1)), u(c.rows));
420	    let (nodes, r, loads, stations) = (u(c.nodes), u(c.constraints), u(c.loads), u(c.stations));
421	    let enc = u(c.source_encoding_len);
422	    let w = wide_bytes;
423	
424	    let harness =
425	        nodes * MODEL_NODE_BYTES + m * MODEL_MEMBER_BYTES + loads * 16 + m * u(s.frame_element);
426	    let source = 24 * nodes
427	        + m * u(s.straight_member)
428	        + r * u(s.constraint)
429	        + loads * (u(s.nodal_load) + SOURCE_ID_BYTES)
430	        + stations * u(s.station)
431	        + 16 * n
432	        + 4 * nodes;
433	    let case = loads * LEDGER_ENTRY_BYTES
434	        + r * PRESCRIBED_ENTRY_BYTES
435	        + enc
436	        + rows * u(s.quantity_meta)
437	        + 8 * u(c.bodies);
438	    let group = 8 * (n + 1)
439	        + 16 * nnz
440	        + 8 * (nnz + 1)
441	        + m * CONTRIBUTIONS_PER_MEMBER * CONTRIBUTION_BYTES
442	        + 32 * nf
443	        + 8 * n
444	        + 12 * nf
445	        + 24 * blocks;
446	    let group_build = m * CONTRIBUTIONS_PER_MEMBER * (TAGGED_CONTRIBUTION_BYTES + 16);
447	    let fixed = harness + 2 * source + case + group;
448	
449	    let shared = ATTEMPT_WIDTHS.map(|(_, l, r)| {
450	        m * (MEMBER_OPERATOR_WIDES * w(l) + MEMBER_OPERATOR_EXTRA)
451	            + nnz * (w(l) + w(r))
452	            + m * (BOUNDED_WIDES * w(r) + BOUNDED_EXTRA)
453	            + p_entries * w(l)
454	            + nf * (FACTOR_ROW_WIDES * w(l) + FACTOR_ROW_EXTRA)
455	            + blocks * w(l)
456	    });
457	    let shared_build = ATTEMPT_WIDTHS.map(|(p, _, r)| {
458	        if p == 1024 {
459	            0
460	        } else {
461	            m * (MEMBER_OPERATOR_WIDES * w(r) + MEMBER_OPERATOR_EXTRA)
462	        }
463	    });
464	    let state = ATTEMPT_WIDTHS.map(|(_, l, _)| (n + 6 * m + rows) * w(l));
465	    // KF1: a solve attempt's trackers (bounded) and their tables.
466	    let solve_trackers = SOLVE_TRACKER_PEAK_ROWS * TRACKER_ENTRY_BYTES
467	        + (VEC_SLACK * SOLVE_TABLE_ROWS_PER_FREE_DOF + TABLE_MOVE_EXTRA)
468	            * nf
469	            * TRACKER_TABLE_ENTRY_BYTES;
470	    // The solve (`K4R/adaptive.rs:1554-1700`): its working vectors and the
471	    // residual gate's row list, then the fallback (`:1437-1500`, RV22-2):
472	    // `u_free`, the evaluated states and `abar_q`, alive throughout; then
473	    // either `assemble_bounded`'s member blocks (while `abar_q` is built) or,
474	    // per state, the copy of u and the row list under the move model.
475	    let solve = ATTEMPT_WIDTHS.map(|(_, l, r)| {
476	        let fallback = nf * w(l)
477	            + EVALUATED_STATES * (nf * w(l) + VEC_HEADER_BYTES)
478	            + nnz * w(r)
479	            + (m * BLOCK_WIDES * w(r))
480	                .max(n * w(l) + fallback_row_list_rows(nf) * TRACKER_ENTRY_BYTES);
481	        SOLVE_VECTORS * n * w(r) + nf * (RESIDUAL_ROW_EXTRA + w(l)) + solve_trackers + fallback
482	    });
483	    let verify = VERIFY_WIDTHS.map(|(_, l, ww)| {
484	        nnz * w(l)
485	            + m * BLOCK_WIDES * w(ww)
486	            + blocks * (BLOCK_BOUND_WIDES * w(l) + BLOCK_BOUND_EXTRA)
487	    });
488	    let verify_build = VERIFY_WIDTHS.map(|(p, l, ww)| {
489	        m * (BOUNDED_WIDES * w(l) + BOUNDED_EXTRA)
490	            + m * BLOCK_WIDES * w(l)
491	            + if p == 1024 {
492	                0
493	            } else {
494	                m * (MEMBER_OPERATOR_WIDES * w(ww) + MEMBER_OPERATOR_EXTRA)
495	            }
496	    });
497	    // The report, kept after the pass: its row vectors and two over the free
498	    // DOFs.
499	    let report = VERIFY_WIDTHS
500	        .map(|(_, l, _)| REPORT_ROW_VECTORS * rows * (w(l) + OPTION_EXTRA) + 2 * nf * w(l));
501	    // The pass (`K4R/verify.rs:731-925`, RV22-2): its locals, with either the
502	    // first three row vectors and the shift's two profiles (`K4R/bound.rs`
503	    // `scaled_profile`, `shifted_factor`) or, after the shift, all five row
504	    // vectors.
505	    let pass = VERIFY_WIDTHS.map(|(_, l, ww)| {
506	        let live = PASS_FULL_VECTORS * n * w(l)
507	            + PASS_FREE_VECTORS * nf * w(l)
508	            + (rows + 6 * m) * w(l)
509	            + n * PASS_PER_DOF_EXTRA
510	            + r * (w(ww) + w(l));
511	        let at_shift = PASS_EARLY_ROW_VECTORS * rows * (w(l) + OPTION_EXTRA)
512	            + p_entries * w(l)
513	            + nf * PROFILE_ROW_EXTRA
514	            + p_entries * w(l)
515	            + nf * (PROFILE_CLONE_ROW_EXTRA + (w(l) + OPTION_EXTRA) + w(l));
516	        let after = REPORT_ROW_VECTORS * rows * (w(l) + OPTION_EXTRA);
517	        live + at_shift.max(after)
518	    });
519	    // KF1: the stop rule's trackers at their peak, and their tables.
520	    let decide = STOP_RULE_PEAK_ROWS * TRACKER_ENTRY_BYTES
521	        + (DECIDE_TRACKER_SETS * VEC_SLACK + TABLE_MOVE_EXTRA) * rows * TRACKER_TABLE_ENTRY_BYTES;
522	    // KF1: the pivot margin's tracker in each shared build, and its table.
523	    let pivot = PIVOT_TRACKER_PEAK_ROWS * TRACKER_ENTRY_BYTES
524	        + (VEC_SLACK + TABLE_MOVE_EXTRA) * nf * TRACKER_TABLE_ENTRY_BYTES;
525	    let end = rows * (u(s.published_row) + 40)
526	        + enc
527	        + (n + 6 * m) * (9 + 8 * 16)
528	        + 8 * u(s.attempt_record);
529	
530	    let mut kept = fixed;
531	    let mut peak = fixed + group_build;
532	    let mut sel128 = 0;
533	    for (k, &(p, _, _)) in ATTEMPT_WIDTHS.iter().enumerate() {
534	        peak = peak.max(kept + shared[k] + shared_build[k] + pivot);
535	        kept += shared[k];
536	        peak = peak.max(kept + state[k] + solve[k]);
537	        kept += state[k];
538	        if let Some(v) = VERIFY_WIDTHS.iter().position(|&(vp, _, _)| vp == p) {
539	            peak = peak.max(kept + verify[v] + verify_build[v]);
540	            kept += verify[v];
541	            peak = peak.max(kept + pass[v]);
542	            peak = peak.max(kept + report[v] + decide);
543	            if p == 256 {
544	                sel128 = peak.max(kept + report[v] + end);
545	            }
546	        }
547	    }
548	    let max = peak.max(kept + report[2] + end);
549	    W1Estimate {
550	        decide,
551	        solve,
552	        pass,
553	        fixed,
554	        shared,
555	        state,
556	        verify,
557	        max,
558	        sel128,
559	    }
560	}
