 1	//! RCM equality (K4's brief Q7; D1 stale item 4; plan §11): K4's port
 2	//! `reverse_cuthill_mckee` (`K4R/factor.rs`) and `sparse_direct`'s
 3	//! (`SD/lib.rs`) must give the same order on the same adjacency. V-K builds
 4	//! the adjacency itself: the free–free DOF graph of a model (members' 12×12
 5	//! blocks, spring diagonals, directional springs' 3×3 node blocks), with the
 6	//! restrained DOFs removed and the free DOFs numbered in ascending order.
 7	use crate::cases::Model;
 8	use open_pipe_stress_frame_kernel::structural::retained_api::reverse_cuthill_mckee as k4_rcm;
 9	use open_pipe_stress_sparse_direct::reverse_cuthill_mckee as sd_rcm;
10	use std::collections::BTreeSet;
